56	export function splitFrontmatter(text: string): { frontmatter: Record<string, string>; body: string } {
57	  const lines = text.split(/\r?\n/)
58	  if (lines[0]?.trim() !== '---') return { frontmatter: {}, body: text }
59	  const end = lines.findIndex((line, i) => i > 0 && line.trim() === '---')
60	  if (end === -1) return { frontmatter: {}, body: text }
61	  const frontmatter: Record<string, string> = {}
62	  for (let i = 1; i < end; i++) {
63	    const match = /^([A-Za-z0-9_-]+):\s*(.*)$/.exec(lines[i]!)
64	    if (!match) continue
65	    const key = match[1]!
66	    const value = match[2]!.trim()
67	    if (/^[>|]-?$/.test(value)) {
68	      const block: string[] = []
69	      while (i + 1 < end && /^\s+\S/.test(lines[i + 1]!)) block.push(lines[++i]!.trim())
70	      frontmatter[key] = block.join(value.startsWith('>') ? ' ' : '\n')
71	    } else {
72	      frontmatter[key] = unquote(value)
73	    }
74	  }
75	  return { frontmatter, body: lines.slice(end + 1).join('\n').replace(/^\n+/, '') }
76	}
