3	/**
4	 * The text with comments blanked and string literals emptied, holes included,
5	 * so that every brace left is code. Every character keeps its place (a
6	 * literal's quotes stay, its content becomes spaces), so line numbers and
7	 * columns still point into the original; a comment-only line comes out blank,
8	 * a line holding only a string keeps its quotes and counts as code.
9	 */
10	export function stripLiterals(text: string, lang: Language): string {
11	  return new Stripper(text, lang).run()
12	}
