14	type Hole = { open: string; close: string }
15	
16	const BRACE_HOLE: Hole = { open: '{', close: '}' }
17	const PAREN_HOLE: Hole = { open: '(', close: ')' }
18	
19	const isIdentChar = (ch: string | undefined): boolean => ch !== undefined && /[\w$]/.test(ch)
