21	class Stripper {
22	  private i = 0
23	  private readonly out: string[] = []
24	
25	  constructor(
26	    private readonly text: string,
27	    private readonly lang: Language,
28	  ) {}
29	
30	  run(): string {
31	    this.code(true)
32	    return this.out.join('')
33	  }
34	
35	  /** Code until the end, or, inside a hole, until the bracket that closes it. */
36	  private code(visible: boolean, hole?: Hole): void {
37	    let depth = 0
38	    while (this.i < this.text.length) {
39	      const c = this.text[this.i]!
40	      if (this.lang.preprocessor && c === '#' && this.atLineStart()) {
41	        this.blankLine(true)
42	        continue
43	      }
44	      if (this.lineCommentAt()) {
45	        this.blankLine(false)
46	        continue
47	      }
48	      if (this.blockCommentAt()) {
49	        this.blockComment()
50	        continue
51	      }
