53	      if (hole) {
54	        if (c === hole.open) depth++
55	        else if (c === hole.close) {
56	          if (depth === 0) {
57	            this.blank()
58	            return
59	          }
60	          depth--
61	        }
62	      }
63	      this.take(visible)
64	    }
